    pub fn ocf_base(&self) -> u32 {
        let mut ocf = self.ocf_base;
        if self.rotateable > 0 {
            ocf |= crate::ocf::ROTATE;
        }
        // OCF_Grab from the Grab DefCore value (C4Object SetOCF).
        if self.grab > 0 {
            ocf |= crate::ocf::GRAB;
        }
        ocf
    }

