    fn call_object_function(
        &mut self,
        index: usize,
        function: &str,
        args: Vec<Value>,
    ) -> Result<Value, EngineError> {
        let (object_id, definition_id, state_snapshot) = {
            let object = self
                .objects
                .get(index)
                .ok_or_else(|| EngineError::UnknownObject(ObjectId::new(u64::MAX)))?;
            (
                object.id,
                object.definition_id.clone(),
                object.script_state_snapshot(),
            )
        };
        let definition = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
        let definitions_ref = &self.definitions;
        let action_library = definition.action_library().clone();
        let rng_state = self.rng.clone();
        let global_view = self.global_effects.clone();
        let world = self.host_world_context();
        let (value, outcome, audio_state, new_rng) = definition.call_object_function(
            &state_snapshot,
            object_id,
            function,
            &args,
            rng_state,
            &global_view,
            self.physics,
            self.environment,
            self.frame,
            world,
            self.game_over_triggered,
            self.audio_registry.clone(),
        )?;
        self.rng = new_rng;
        self.audio_registry = audio_state;
        self.apply_action_callback_outcome(
            index,
            outcome,
            &action_library,
            object_id,
            &definition_id,
        )?;
        Ok(value)
    }

    fn call_movement_object_function(
        &mut self,
        index: usize,
        function: &str,
        args: &[Value],
        action_library: &ActionLibrary,
        object_id: ObjectId,
        definition_id: &str,
    ) -> Result<Value, EngineError> {
        let state_snapshot = self
            .objects
            .get(index)
            .ok_or_else(|| EngineError::UnknownObject(ObjectId::new(u64::MAX)))?
            .state
            .clone();
        let definition = self
            .definitions
            .get(definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.to_string()))?;
        let definitions_ref = &self.definitions;
        let rng_state = self.rng.clone();
        let global_view = self.global_effects.clone();
        let world = self.host_world_context();
        let (value, outcome, audio_state, new_rng) = definition.call_object_function(
            &state_snapshot,
            object_id,
            function,
            args,
            rng_state,
            &global_view,
            self.physics,
            self.environment,
            self.frame,
            world,
            self.game_over_triggered,
            self.audio_registry.clone(),
        )?;
        self.rng = new_rng;
        self.audio_registry = audio_state;
        self.apply_callback_outcome(
            index,
            outcome,
            action_library,
            object_id,
            definition_id,
            false,
        )?;
        Ok(value)
    }

    fn invoke_movement_hit_callbacks(
        &mut self,
        index: usize,
        old_velocity: FixedVec2,
        hit_speed_flags: u32,
        action_library: &ActionLibrary,
        object_id: ObjectId,
        definition_id: &str,
    ) -> Result<(), EngineError> {
        let args = [
            Value::Int(fixtoi_prec(old_velocity.x, 100)),
            Value::Int(fixtoi_prec(old_velocity.y, 100)),
        ];
        for (flag, function) in [
            (crate::ocf::HIT_SPEED1, "Hit"),
            (crate::ocf::HIT_SPEED2, "Hit2"),
            (crate::ocf::HIT_SPEED3, "Hit3"),
        ] {
            if hit_speed_flags & flag == 0 {
                continue;
            }
            // Engine-initiated lifecycle calls are fail-safe: a script
            // error in Hit/Hit2/Hit3 logs and the tick continues
            // (C4AulExec.cpp:1318-1342) — it must never kill the frame.
            if let Err(error) = self.call_movement_object_function(
                index,
                function,
                &args,
                action_library,
                object_id,
                definition_id,
            ) {
                tracing::warn!(
                    definition = %definition_id,
                    function,
                    %error,
                    "script error in engine callback; continuing like the C++ fail-safe exec"
                );
            }
        }
        Ok(())
    }

    pub fn handle_control_command(
        &mut self,
        owner: i32,
        command: ControlCommand,
        kind: CommandKind,
    ) -> Result<bool, EngineError> {
        let Some(function_name) = control_function_name(command, kind) else {
            return Ok(false);
        };

        self.ensure_cursor(owner)?;
        let Some(cursor) = self.crew_cursor(owner) else {
            return Ok(false);
        };

        let index = self
            .objects
            .iter()
            .position(|object| object.id == cursor)
            .ok_or(EngineError::UnknownObject(cursor))?;

        // C4Object::DirectCom (C4Object.cpp:3363-3367): a contained clonk
        // hands every non-Special com to its container and DirectCom
        // returns — the clonk's own Control<Com> is never consulted.
        if !matches!(command, ControlCommand::Special | ControlCommand::Special2) {
            if let Some(container) = self.objects[index].state.container {
                return self.contained_control(index, cursor, container, command, kind);
            }
        }

        let definition_id = self.objects[index].definition_id.clone();
        let state_snapshot = self.objects[index].script_state_snapshot();
        let definition = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
        let definitions_ref = &self.definitions;
        let action_library = definition.action_library().clone();
        let rng_state = self.rng.clone();
        let global_view = self.global_effects.clone();
        let world = self.host_world_context();
        let (handled, outcome, audio_state, new_rng) = definition.call_control(
            &state_snapshot,
            cursor,
            &function_name,
            rng_state,
            &global_view,
            self.physics,
            self.environment,
            self.frame,
            world,
            self.game_over_triggered,
            self.audio_registry.clone(),
        )?;
        self.rng = new_rng;
        self.audio_registry = audio_state;
        self.apply_action_callback_outcome(
            index,
            outcome,
            &action_library,
            cursor,
            &definition_id,
        )?;
        Ok(handled)
    }

    /// C4Object::ContainedControl script dispatch (C4Object.cpp:3208-3306):
    /// the container's `Contained<Com>` function runs with the container as
    /// context and the clonk as parameter (`sf->Exec(Contained,
    /// {C4VObj(this)})`, :3221,3230) after the controller propagates
    /// (`Contained->Controller = Controller`, :3367). The com is consumed
    /// either way — DirectCom returns unconditionally. The hardcoded
    /// non-script fallbacks (COM_Down exit, COM_Throw command,
    /// COM_Up/COM_Dig base buy/sell, Take/Take2; :3243-3306) are command-AI
    /// features not yet ported — see PORT_STATUS.
    fn contained_control(
        &mut self,
        crew_index: usize,
        crew_id: ObjectId,
        container: ObjectId,
        command: ControlCommand,
        kind: CommandKind,
    ) -> Result<bool, EngineError> {
        let Some(container_index) = self.find_object_index(container) else {
            return Ok(true);
        };
        let controller = self.objects[crew_index].state.controller;
        self.objects[container_index].state.controller = controller;
        let Some(function) = com_name(command, kind).map(|com| format!("Contained{com}")) else {
            return Ok(true);
        };
        let definition_id = self.objects[container_index].definition_id.clone();
        let action_library = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?
            .action_library()
            .clone();
        let args = [compat::object_reference_value(crew_id)];
        self.call_movement_object_function(
            container_index,
            &function,
            &args,
            &action_library,
            container,
            &definition_id,
        )?;
        Ok(true)
    }

    pub fn try_grab_nearby(&mut self, owner: i32) -> Result<bool, EngineError> {
        self.ensure_cursor(owner)?;
        let Some(crew_id) = self.crew_cursor(owner) else {
            return Ok(false);
        };
        let crew_index = match self.find_object_index(crew_id) {
            Some(index) => index,
            None => return Err(EngineError::UnknownObject(crew_id)),
        };
        if !self.objects[crew_index].state.status.is_active() {
            return Ok(false);
        }
        let crew_position = self.objects[crew_index].state.position;
        let Some((_, target_id)) =
            self.find_nearby_object_with_mask(crew_id, crew_position, ocf::GRAB, 22, |object| {
                object.state.container.is_none() && object.state.status.is_active()
            })
        else {
            return Ok(false);
        };
        let update = ObjectUpdate::new()
            .with_container(crew_id)
            .with_position(crew_position)
            .with_velocity(Vector2::ZERO);
        self.apply_object_update(target_id, update)?;
        Ok(true)
    }

    pub fn try_drop_held_object(&mut self, owner: i32) -> Result<bool, EngineError> {
        self.ensure_cursor(owner)?;
        let Some(crew_id) = self.crew_cursor(owner) else {
            return Ok(false);
        };
        let crew_index = match self.find_object_index(crew_id) {
            Some(index) => index,
            None => return Err(EngineError::UnknownObject(crew_id)),
        };
        let crew_state = &self.objects[crew_index].state;
        if !crew_state.status.is_active() {
            return Ok(false);
        }
        let Some(item_id) = crew_state.contents.first().copied() else {
            return Ok(false);
        };
        let offset = match crew_state.direction {
            Direction::Left => -8,
            Direction::Right => 8,
        };
        let drop_position = Vector2::new(crew_state.position.x + offset, crew_state.position.y);
        let update = ObjectUpdate::new()
            .clear_container()
            .with_position(drop_position)
            .with_velocity(Vector2::ZERO);
        self.apply_object_update(item_id, update)?;
        Ok(true)
    }

    pub fn try_enter_nearby(&mut self, owner: i32) -> Result<bool, EngineError> {
        self.ensure_cursor(owner)?;
        let Some(crew_id) = self.crew_cursor(owner) else {
            return Ok(false);
        };
        let crew_index = match self.find_object_index(crew_id) {
            Some(index) => index,
            None => return Err(EngineError::UnknownObject(crew_id)),
        };
        let crew_state = &self.objects[crew_index].state;
        if crew_state.container.is_some() || !crew_state.status.is_active() {
            return Ok(false);
        }
        let crew_position = crew_state.position;
        let Some((target_index, target_id)) = self.find_nearby_object_with_mask(
            crew_id,
            crew_position,
            ocf::ENTRANCE,
            24,
            |object| object.state.status.is_active(),
        ) else {
            return Ok(false);
        };
        let target_position = self.objects[target_index].state.position;
        let update = ObjectUpdate::new()
            .with_container(target_id)
            .with_position(target_position)
            .with_velocity(Vector2::ZERO);
        self.apply_object_update(crew_id, update)?;
        Ok(true)
    }

    pub fn set_crew_role(
        &mut self,
        owner: i32,
        object_id: ObjectId,
        role: CrewRole,
    ) -> Result<(), EngineError> {
        if role.as_str().trim().is_empty() {
            return Err(EngineError::CrewRole {
                owner,
                detail: "role name must not be empty".to_string(),
            });
        }

        let object = self
            .objects
            .iter()
            .find(|object| object.id == object_id)
            .ok_or(EngineError::UnknownObject(object_id))?;
        if object.state.owner != owner {
            return Err(EngineError::CrewRole {
                owner,
                detail: format!("object {} is owned by {}", object_id, object.state.owner),
            });
        }
        if !object.state.crew_member {
            return Err(EngineError::CrewRole {
                owner,
                detail: format!("object {} is not a crew member", object_id),
            });
        }
        if !object.state.status.is_active() {
            return Err(EngineError::CrewRole {
                owner,
                detail: format!("object {} is not active", object_id),
            });
        }

        self.crew_roles
            .entry(owner)
            .or_default()
            .insert(object_id, role);
        Ok(())
    }

    pub fn crew_role(&self, owner: i32, object_id: ObjectId) -> Option<&CrewRole> {
        self.crew_roles
            .get(&owner)
            .and_then(|roles| roles.get(&object_id))
    }

    pub fn crew_role_assignments(&self, owner: i32) -> HashMap<ObjectId, CrewRole> {
        self.crew_roles.get(&owner).cloned().unwrap_or_default()
    }

    pub fn clear_crew_role(&mut self, owner: i32, object_id: ObjectId) {
        if let Some(assignments) = self.crew_roles.get_mut(&owner) {
            assignments.remove(&object_id);
            if assignments.is_empty() {
                self.crew_roles.remove(&owner);
            }
        }
    }

    pub fn clear_roles_for_owner(&mut self, owner: i32) {
        self.crew_roles.remove(&owner);
    }

    pub fn apply_command(
        &mut self,
        owner: i32,
        target: CrewCommandTarget,
        update: ObjectUpdate,
    ) -> Result<(), EngineError> {
        self.prune_roles();
        let mut recipients = self.resolve_command_targets(owner, &target);
        if recipients.is_empty() {
            return Ok(());
        }

        let mut seen = HashSet::new();
        recipients.retain(|id| seen.insert(*id));
        if recipients.len() > 1 {
            let ordering: HashMap<_, _> = self
                .objects
                .iter()
                .enumerate()
                .map(|(index, object)| (object.id, index))
                .collect();
            recipients.sort_by_key(|id| ordering.get(id).copied().unwrap_or(usize::MAX));
        }
        for object_id in recipients {
            self.apply_object_update(object_id, update.clone())?;
        }
        Ok(())
    }

    pub fn global_effects(&self) -> &[EffectState] {
        &self.global_effects
    }

    pub fn register_definition(&mut self, definition: Definition) -> Result<(), EngineError> {

        // A def script's `global func`s land on the ENGINE scope like any
        // System.c4g global (C4AulParse "global" storage — the GoldRush
        // Talker's StartMovie is called from the scenario script). They
        // join the global table with the same overload chaining as
        // install_additional_global_scripts.
        let def_globals: Vec<(String, lc_script::Function)> = definition
            .script
            .global_access_functions()
            .map(|(name, function)| (name.clone(), function.clone()))
            .collect();
        if !def_globals.is_empty() {
            let mut functions: HashMap<String, lc_script::Function> = self
                .global_script_functions
                .as_deref()
                .cloned()
                .unwrap_or_default();
            for (function_name, mut function) in def_globals {
                if let Some(previous) = functions.remove(&function_name) {
                    function.push_overload(previous);
                }
                functions.insert(function_name, function);
            }
            let table = Some(Arc::new(functions));
            self.global_script_functions = table.clone();
            for existing in self.definitions.values_mut() {
                existing.set_global_functions(table.clone());
            }
            if let Some(script) = self.scenario_script.as_mut() {
                script.set_global_functions(table.clone());
            }
        }
        let id = definition.id().to_string();
        if self.definitions.contains_key(&id) {
            return Err(EngineError::DefinitionAlreadyExists(id));
        }
        let mut definition = definition;
        definition.set_global_functions(self.global_script_functions.clone());
        {
            // One GlobalNamed table for every script host: `static`
            // declarations compiled into the definition move to it.
            let script = Arc::make_mut(&mut definition.script);
            script.set_global_variables(self.script_globals.clone());
            script.set_global_constants(self.script_global_consts.clone());
            script.adopt_statics_into_globals();
        }
        self.definition_load_order
            .push(DefinitionId::from(id.as_str()));
        self.definitions.insert(id, definition);
        self.definition_metadata_cache.borrow_mut().take();
        Ok(())
    }

    /// Installs the engine-global script functions — the System.c4g
    /// `global func`s that C++ owns on `Game.ScriptEngine`
    /// (resolution per FindSameNameFunc: own-def script first, engine-owned
    /// fallback, C4Aul.cpp:130-148). Scripts that fail to compile log and
    /// are skipped like C++. The table is shared into every registered
    /// (and future) script host.
    pub fn install_global_scripts(&mut self, sources: &[(String, String)]) -> usize {
        self.global_script_functions = None;
        self.system_append_scripts.clear();
        self.install_additional_global_scripts(sources)
    }

    /// Adds global scripts ON TOP of the installed table: later definitions
    /// overload earlier ones and `inherited` reaches them (C++ link order —
    /// the scenario's System.c4g joins the engine's, C4Game.cpp:3317-3343).
    pub fn install_additional_global_scripts(&mut self, sources: &[(String, String)]) -> usize {
        let mut functions: HashMap<String, lc_script::Function> = self
            .global_script_functions
            .as_deref()
            .cloned()
            .unwrap_or_default();
        let mut loaded = 0usize;
        for (name, source) in sources {
            match lc_script::Script::compile(source) {
                Ok(script) => {
                    // Scripts with #appendto also append their functions to
                    // the named definitions at link time (C4AulLink.cpp:
                    // 29-64; system hosts register before defs in C++).
                    if !script.appends().is_empty() {
                        self.system_append_scripts.push(script.clone());
                    }
                    // `static` declarations register engine-globally
                    // (GlobalNamed) regardless of which host declared them.
                    for var_decl in script.var_decls() {
                        if var_decl.kind == lc_script::VarDeclKind::Static {
                            self.script_globals
                                .borrow_mut()
                                .entry(var_decl.name.clone())
                                .or_insert_with(|| lc_script::value_cell(lc_script::Value::Nil));
                        }
                    }
                    for (function_name, function) in script.functions() {
                        let mut function = function.clone();
                        if let Some(previous) = functions.remove(function_name) {
                            function.push_overload(previous);
                        }
                        functions.insert(function_name.clone(), function);
                    }
                    loaded += 1;
                }
                Err(error) => {
                    tracing::warn!(
                        script = %name,
                        %error,
                        "global script failed to compile; skipping like C++"
                    );
                }
            }
        }
        let table = (!functions.is_empty()).then(|| Arc::new(functions));
        self.global_script_functions = table.clone();
        for definition in self.definitions.values_mut() {
            definition.set_global_functions(table.clone());
        }
        if let Some(script) = self.scenario_script.as_mut() {
            script.set_global_functions(table.clone());
        }
        loaded
    }

    /// `C4AulScript::ResolveAppends` (C4AulLink.cpp:29-64): every script's
    /// `#appendto` targets receive a COPY of its non-global functions as
    /// overrides (AppendTo with bHighPrio, :114-141). MUST run before
    /// include resolution (":27-28 ResolveAppends has to be called
    /// first!"). System hosts register before definitions in C++, so
    /// their appends apply first; definitions follow in registration
    /// order — that order decides the overload chain when several appends
    /// hit the same target function. Unknown targets warn and skip
    /// (:42-49); `#appendto *` reaches every definition except the source
    /// (:53-60).
    pub fn resolve_appends(&mut self) {
        enum AppendSource {
            System(usize),
            Definition(DefinitionId),
        }
        let mut work: Vec<(AppendSource, Vec<lc_script::AppendTo>)> = self
            .system_append_scripts
            .iter()
            .enumerate()
            .map(|(index, script)| (AppendSource::System(index), script.appends().to_vec()))
            .collect();
        for id in &self.definition_load_order {
            if let Some(definition) = self.definitions.get(id) {
                if !definition.appends.is_empty() {
                    work.push((
                        AppendSource::Definition(id.clone()),
                        definition.appends.clone(),
                    ));
                }
            }
        }
        if work.is_empty() {
            return;
        }

        let ordered_ids = self.definition_load_order.clone();
        for (source, targets) in work {
            let (source_script, source_id) = match &source {
                AppendSource::System(index) => {
                    let mut engine = ScriptEngine::new();
                    // Statics in append scripts are engine-global, never
                    // object locals of the append target.
                    engine.set_global_variables(self.script_globals.clone());
                    engine.add_script(self.system_append_scripts[*index].clone());
                    #[allow(clippy::arc_with_non_send_sync)] // single-threaded sharing
                    (Arc::new(engine), None)
                }
                AppendSource::Definition(id) => match self.definitions.get(id) {
                    Some(definition) => (definition.script.clone(), Some(id.clone())),
                    None => continue,
                },
            };
            for target in targets {
                let resolved: Vec<DefinitionId> = match &target {
                    lc_script::AppendTo::Id(token) => {
                        let id = DefinitionId::from(token.as_str());
                        if self.definitions.contains_key(&id) {
                            vec![id]
                        } else {
                            // "script to #appendto not found"
                            // (C4AulLink.cpp:42-49) — a warning, never an
                            // error.
                            tracing::warn!(target = %token, "script to #appendto not found");
                            Vec::new()
                        }
                    }
                    lc_script::AppendTo::Wildcard => ordered_ids
                        .iter()
                        .filter(|id| Some(*id) != source_id.as_ref())
                        .cloned()
                        .collect(),
                };
                for target_id in resolved {
                    if let Some(definition) = self.definitions.get_mut(&target_id) {
                        Arc::make_mut(&mut definition.script).append_overrides_from(&source_script);
                        definition.refresh_script_flags();
                    }
                }
            }
        }
        self.definition_metadata_cache.borrow_mut().take();
    }

    /// Registers `global func` declarations from DEFINITION scripts into
    /// the engine-global table (C4Aul AA_GLOBAL functions are owned by
    /// Game.ScriptEngine — Time.c4d's IsNight, MainTipi's GetClan):
    /// applied on top of the installed System.c4g table in definition
    /// load order, later declarations overloading earlier ones, then
    /// re-shared to every script host.
    pub fn collect_definition_global_functions(&mut self) {
        let mut functions: HashMap<String, lc_script::Function> = self
            .global_script_functions
            .as_deref()
            .cloned()
            .unwrap_or_default();
        let mut changed = false;
        for id in &self.definition_load_order {
            let Some(definition) = self.definitions.get(id) else {
                continue;
            };
            for (name, function) in definition.script.global_access_functions() {
                let mut function = function.clone();
                if let Some(previous) = functions.remove(name) {
                    function.push_overload(previous);
                }
                functions.insert(name.clone(), function);
                changed = true;
            }
        }
        if !changed {
            return;
        }
        let table = Some(Arc::new(functions));
        self.global_script_functions = table.clone();
        for definition in self.definitions.values_mut() {
            definition.set_global_functions(table.clone());
        }
        if let Some(script) = self.scenario_script.as_mut() {
            script.set_global_functions(table.clone());
        }
        self.definition_metadata_cache.borrow_mut().take();
    }

    pub fn resolve_includes(&mut self) -> Result<(), EngineError> {
        self.definition_metadata_cache.borrow_mut().take();
        // Iteratively merge includes until no more changes occur
        // This ensures transitive dependencies are fully resolved
        // (e.g., TRE2 -> TRE1 -> TREE means TRE2 gets functions from TREE)
        let mut changed = true;

        while changed {
            changed = false;

            // Collect all definitions that have includes
            let ids_with_includes: Vec<String> = self
                .definitions
                .iter()
                .filter(|(_, def)| !def.includes().is_empty())
                .map(|(id, _)| id.clone())
                .collect();

            // For each definition with includes, merge parent functions
            for child_id in ids_with_includes {
                let includes = self
                    .definitions
                    .get(&child_id)
                    .map(|def| def.includes().to_vec())
                    .unwrap_or_default();

                for parent_id in &includes {
                    // Check if parent exists
                    if !self.definitions.contains_key(parent_id) {
                        return Err(EngineError::UnknownDefinition(parent_id.clone()));
                    }

                    // Clone the parent to avoid borrow checker issues
                    let parent = self.definitions.get(parent_id).unwrap().clone();

                    // Count functions before merge to detect changes
                    let before_count = self
                        .definitions
                        .get(&child_id)
                        .map(|def| def.function_count())
                        .unwrap_or(0);

                    // Merge parent into child
                    if let Some(child) = self.definitions.get_mut(&child_id) {
                        child.merge_from(&parent);

                        // Check if we added any functions
                        let after_count = child.function_count();
                        if after_count > before_count {
                            changed = true;
                        }
                    }
                }
            }
        }

        Ok(())
    }

