    // FnDistance (C4Script.cpp:3316-3319) -> Distance (C4Math.cpp:22-31):
    // integer euclidean distance with the exact post-sqrt adjustment;
    // FnSetViewOffset (C4Script.cpp:5676-5687): ValidPlr gate, then true
    // even without a viewport (sync safety — the headless C++ path).
    // Both run in System.c4g's FxShakeEffectTimer (Explode.c:188-200).
    #[test]
    fn distance_and_set_view_offset_match_cpp() {
        let caller_script = r#"#strict
local iPyth, iDiag, iZero, iBadPlr, iGoodPlr;
func Trigger() {
    iPyth = Distance(0, 0, 3, 4);
    iDiag = Distance(0, 0, 1, 1);
    iZero = Distance(-7, 9, -7, 9);
    iBadPlr = SetViewOffset(9, 5, 5);
    iGoodPlr = SetViewOffset(1, 5, 5);
    return(1);
}
"#;
        let mut engine = Engine::with_seed(0);
        engine
            .register_player(PlayerConfig::new(1, "P1"))
            .expect("player registers");
        engine
            .register_definition(
                Definition::from_script("CALL", "Caller", caller_script).expect("caller compiles"),
            )
            .expect("caller registers");

        let id = engine
            .spawn_object(SpawnConfig::new("CALL").with_category(CATEGORY_OBJECT))
            .expect("caller spawns");
        let idx = engine.find_object_index(id).expect("caller exists");
        engine
            .call_object_function(idx, "Trigger", Vec::new())
            .expect("trigger runs");

        let idx = engine.find_object_index(id).expect("caller exists");
        let locals = &engine.objects[idx].state.local_vars;
        assert_eq!(locals.get("iPyth"), Some(&Value::Int(5)));
        assert_eq!(
            locals.get("iDiag"),
            Some(&Value::Int(1)),
            "sqrt(2) adjusts down to the floor (C4Math.cpp:28-30)"
        );
        assert_eq!(locals.get("iZero"), Some(&Value::Int(0)));
        assert_eq!(
            locals.get("iBadPlr"),
            Some(&Value::Bool(false)),
            "invalid player rejected"
        );
        assert_eq!(
            locals.get("iGoodPlr"),
            Some(&Value::Bool(true)),
            "no viewport is sync-safe true"
        );
    }

    #[test]
    fn call_runs_own_def_script_function_like_cpp() {
        // FnCall (C4Script.cpp:3424-3432): Call(name, p0..p8) runs `name` on
        // the calling object itself (C4Object::Call → own def script,
        // AA_PRIVATE, C4Object.cpp:2197-2201). Resolution is owner-scoped
        // script functions ONLY — engine (host) functions are never found
        // (GetSFunc → FuncLookUp.GetFunc(name, owner), C4Aul.cpp:295-298,
        // 562-576) — and a missing function returns C4VNull either way ('~'
        // only silences the log, C4Aul.cpp:314-330). Runtime errors in the
        // callee propagate (fPassErrors=true, C4Script.cpp:3431).
        let script = r#"
        func Helper(a, b) {
            DoEnergy(0 - a);
            return a * b;
        }
        global func Run() { return Call("Helper", 6, 7); }
        global func RunMissing() { return Call("NoSuchHelper"); }
        global func RunFailsafe() { return Call("~NoSuchHelper"); }
        global func RunEngineFn() { return Call("GetWind"); }
        "#;

        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("CLLR", "Caller", script).expect("script compiles"),
            )
            .expect("definition registers");
        let id = engine
            .spawn_object(SpawnConfig::new("CLLR").with_energy(50))
            .expect("object spawns");
        engine.tick().expect("tick succeeds");

        let idx = engine.find_object_index(id).expect("object exists");
        let energy_before = engine.objects[idx].state.energy;
        let result = engine
            .call_object_function(idx, "Run", Vec::new())
            .expect("Run succeeds");
        assert_eq!(result, Value::Int(42), "callee return value verbatim");
        let idx = engine.find_object_index(id).expect("object exists");
        assert!(
            engine.objects[idx].state.energy < energy_before,
            "the callee's DoEnergy on `this` committed (live scope, in-place path)"
        );

        for function in ["RunMissing", "RunFailsafe", "RunEngineFn"] {
            let result = engine
                .call_object_function(idx, function, Vec::new())
                .expect("call-family misses are not errors");
            assert_eq!(
                result,
                Value::Nil,
                "{function}: missing/engine-only functions return C4VNull"
            );
        }
    }

    #[test]
    fn arrow_calls_resolve_on_the_target_object_like_cpp() {
        // `obj->Method(args)` is AB_CALL (C4AulExec.cpp:1216-1305): the
        // function resolves on the TARGET's def via FindSameNameFunc
        // (C4Aul.cpp:130-148 — own script functions, then global/engine
        // functions running with the TARGET's context). `->~` forgives only
        // a MISSING FUNCTION (:1262-1267); a falsy target throws even for
        // `->~` (:1224-1226).
        let caller_script = r#"
        global func Poke(target) { return target->Secret(21); }
        global func PokeMissing(target) { return target->NoSuch(); }
        global func PokeMissingSafe(target) { return target->~NoSuch(); }
        global func PokeNil() { return nil->~Anything(); }
        global func PokeEngineFn(target) { return target->GetID(); }
        "#;
        let probe_script = r#"
        local tag;
        public func Secret(v) {
            tag = v;
            return v * 2;
        }
        "#;

        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("CLLR", "Caller", caller_script).expect("caller compiles"),
            )
            .expect("caller registers");
        engine
            .register_definition(
                Definition::from_script("PROB", "Probe", probe_script).expect("probe compiles"),
            )
            .expect("probe registers");
        let caller = engine
            .spawn_object(SpawnConfig::new("CLLR"))
            .expect("caller spawns");
        let probe = engine
            .spawn_object(SpawnConfig::new("PROB"))
            .expect("probe spawns");
        engine.tick().expect("tick succeeds");

        let caller_idx = engine.find_object_index(caller).expect("caller exists");
        let target_arg = vec![Value::Object(probe.as_u64())];

        // Resolves Secret on PROB (the caller has no Secret) and runs it
        // with PROB's context: its local var commits.
        let result = engine
            .call_object_function(caller_idx, "Poke", target_arg.clone())
            .expect("arrow call succeeds");
        assert_eq!(result, Value::Int(42));
        let probe_idx = engine.find_object_index(probe).expect("probe exists");
        assert_eq!(
            engine.objects[probe_idx].state.local_vars.get("tag"),
            Some(&Value::Int(21)),
            "the callee ran on the TARGET object"
        );

        // Engine functions resolve through the FindSameNameFunc global
        // fallback and run with the TARGET's context.
        let result = engine
            .call_object_function(caller_idx, "PokeEngineFn", target_arg.clone())
            .expect("engine-fn arrow call succeeds");
        assert_eq!(result, Value::C4Id("PROB".into()), "GetID of the TARGET");

        // Missing function: error for `->`, nil for `->~`.
        // (The engine wraps the VM error; the distinction that matters is
        // error-vs-nil between -> and ->~ below.)
        engine
            .call_object_function(caller_idx, "PokeMissing", target_arg.clone())
            .expect_err("missing function on -> is an error");
        let result = engine
            .call_object_function(caller_idx, "PokeMissingSafe", target_arg)
            .expect("->~ forgives the missing function");
        assert_eq!(result, Value::Nil);

        // Falsy target: error even for `->~` (the exact "target is zero"
        // message is pinned by the lc-script unit test).
        engine
            .call_object_function(caller_idx, "PokeNil", Vec::new())
            .expect_err("falsy target throws even for ->~");
    }

    #[test]
    fn object_call_family_runs_target_def_script_function_like_cpp() {
        // FnObjectCall/FnProtectedCall/FnPrivateCall (C4Script.cpp:3434-3449,
        // 3502-3534): all three resolve in the TARGET object's def script
        // with failsafe=true (silent C4VNull on a miss). The access-level
        // difference (AA_PUBLIC vs AA_PROTECTED vs AA_PRIVATE) only LOGS on
        // violation — the call still executes ("don't even break in strict
        // execution", C4Aul.cpp:332-342) — so behavior is identical, and
        // even a `private func` runs via plain ObjectCall. Nil target →
        // C4VNull; script pars[2..=9] shift to callee Par(0..=7).
        let caller_script = r#"
        global func Poke(target) { return ObjectCall(target, "Secret", 21); }
        global func PokeProtected(target) { return ProtectedCall(target, "Secret", 5); }
        global func PokePrivate(target) { return PrivateCall(target, "Secret", 7); }
        global func PokeNil() { return ObjectCall(0, "Secret"); }
        global func PokeMissing(target) { return ObjectCall(target, "NoSuch"); }
        "#;
        let probe_script = r#"
        local tag;
        private func Secret(v) {
            tag = tag + v;
            return v * 2;
        }
        "#;

        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("CLLR", "Caller", caller_script).expect("caller compiles"),
            )
            .expect("caller registers");
        engine
            .register_definition(
                Definition::from_script("PROB", "Probe", probe_script).expect("probe compiles"),
            )
            .expect("probe registers");
        let caller = engine
            .spawn_object(SpawnConfig::new("CLLR"))
            .expect("caller spawns");
        let probe = engine
            .spawn_object(SpawnConfig::new("PROB"))
            .expect("probe spawns");
        engine.tick().expect("tick succeeds");

        let caller_idx = engine.find_object_index(caller).expect("caller exists");
        let target_arg = vec![Value::Object(probe.as_u64())];
        for (function, expected) in [
            ("Poke", Value::Int(42)),
            ("PokeProtected", Value::Int(10)),
            ("PokePrivate", Value::Int(14)),
        ] {
            let result = engine
                .call_object_function(caller_idx, function, target_arg.clone())
                .expect("call succeeds");
            assert_eq!(result, expected, "{function}: callee return verbatim");
        }
        let probe_idx = engine.find_object_index(probe).expect("probe exists");
        assert_eq!(
            engine.objects[probe_idx].state.local_vars.get("tag"),
            Some(&Value::Int(33)),
            "the target's local-var writes committed (21 + 5 + 7)"
        );

        let result = engine
            .call_object_function(caller_idx, "PokeNil", Vec::new())
            .expect("nil target is not an error");
        assert_eq!(result, Value::Nil, "nil target → C4VNull");
        let result = engine
            .call_object_function(caller_idx, "PokeMissing", target_arg)
            .expect("missing function is not an error");
        assert_eq!(result, Value::Nil, "failsafe miss → C4VNull");
    }

    #[test]
    fn definition_call_runs_def_script_without_object_context_like_cpp() {
        // FnDefinitionCall (C4Script.cpp:3451-3468): DefinitionCall(id, name,
        // p0..p7) runs `name` on the DEFINITION's script with Obj=nullptr —
        // always failsafe (the "~" prefix, :3457-3459), so a miss or an
        // unknown id is a silent C4VNull. The callee has no object context.
        let caller_script = r#"
        global func Spawn(targetdef) { return DefinitionCall(targetdef, "Factory", 4); }
        global func SpawnMissing(targetdef) { return DefinitionCall(targetdef, "NoSuch"); }
        global func SpawnBadId() { return DefinitionCall("XXXX", "Factory"); }
        "#;
        let factory_script = r#"
        func Factory(n) {
            if (this()) { return 0 - 1; }
            return n * 11;
        }
        "#;

        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("CLLR", "Caller", caller_script).expect("caller compiles"),
            )
            .expect("caller registers");
        engine
            .register_definition(
                Definition::from_script("FCTY", "Factory", factory_script)
                    .expect("factory compiles"),
            )
            .expect("factory registers");
        let caller = engine
            .spawn_object(SpawnConfig::new("CLLR"))
            .expect("caller spawns");
        engine.tick().expect("tick succeeds");

        let caller_idx = engine.find_object_index(caller).expect("caller exists");
        let result = engine
            .call_object_function(caller_idx, "Spawn", vec![Value::C4Id("FCTY".into())])
            .expect("Spawn succeeds");
        assert_eq!(
            result,
            Value::Int(44),
            "the def-script function ran with no object context (this() nil)"
        );
        let result = engine
            .call_object_function(caller_idx, "SpawnMissing", vec![Value::C4Id("FCTY".into())])
            .expect("missing function is not an error");
        assert_eq!(result, Value::Nil);
        let result = engine
            .call_object_function(caller_idx, "SpawnBadId", Vec::new())
            .expect("unknown id is not an error");
        assert_eq!(result, Value::Nil, "C4Id2Def failure → C4VNull");
    }

    #[test]
    fn game_call_runs_scenario_script_function_like_cpp() {
        // FnGameCall (C4Script.cpp:3470-3484): scenario script host ONLY,
        // always failsafe, Obj=nullptr. The lookup is owner-scoped — a
        // `global func` in a definition's script is NOT found
        // (C4Aul.cpp:295-298,562-576).
        let caller_script = r#"
        global func CallerGlobal() { return 99; }
        global func Ping() { return GameCall("Answer", 6); }
        global func PingMissing() { return GameCall("NoSuch"); }
        global func PingDefGlobal() { return GameCall("CallerGlobal"); }
        "#;

        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("CLLR", "Caller", caller_script).expect("caller compiles"),
            )
            .expect("caller registers");
        engine
            .install_scenario_script(
                "Scenario",
                r#"
                global func Answer(n) { return n * 7; }
                "#,
            )
            .expect("scenario installs");
        let caller = engine
            .spawn_object(SpawnConfig::new("CLLR"))
            .expect("caller spawns");
        engine.tick().expect("tick succeeds");

        let caller_idx = engine.find_object_index(caller).expect("caller exists");
        let result = engine
            .call_object_function(caller_idx, "Ping", Vec::new())
            .expect("Ping succeeds");
        assert_eq!(result, Value::Int(42));
        let result = engine
            .call_object_function(caller_idx, "PingMissing", Vec::new())
            .expect("missing is not an error");
        assert_eq!(result, Value::Nil);
        let result = engine
            .call_object_function(caller_idx, "PingDefGlobal", Vec::new())
            .expect("def-script global is not visible to GameCall");
        assert_eq!(
            result,
            Value::Nil,
            "owner-scoped lookup: definition globals are not in the scenario host"
        );
    }

    #[test]
    fn definition_category_exposes_defcore_category_bits() {
        // Menus filter goal/rule objects by their DefCore Category
        // (C4MainMenu.cpp:392-400).
        let mut engine = Engine::with_seed(7);
        let mut goal_def =
            Definition::from_script("GOAL", "Goal", "").expect("goal compiles");
        goal_def.set_category(1 << 5); // C4D_Goal
        engine
            .register_definition(goal_def)
            .expect("goal registers");
        // normalize_category keeps the goal bit (a display-category default
        // may be OR'd in, mirroring C4Def defaults).
        let category = engine.definition_category("GOAL").expect("category");
        assert_ne!(category & (1 << 5), 0);
        assert_eq!(engine.definition_category("NONE"), None);
    }

    #[test]
    fn game_call_ex_broadcasts_to_goal_rule_environment_objects_like_cpp() {
        // FnGameCallEx (C4Script.cpp:3486-3500) → GRBroadcast
        // (C4ScriptHost.cpp:234-248): every LIVE object whose Category has
        // a C4D_Goal|C4D_Rule|C4D_Environment bit is called first (list
        // order, results DISCARDED — fRejectTest=false), then the scenario
        // script; only the scenario result is returned. Plain-category
        // objects are never called.
        let caller_script = r#"
        global func Shout() { return GameCallEx("Roll", 5); }
        "#;
        let listener_script = r#"
        local hits;
        func Roll(n) {
            hits = hits + n;
            return 1000; // discarded by the broadcast
        }
        "#;

        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("CLLR", "Caller", caller_script).expect("caller compiles"),
            )
            .expect("caller registers");
        let mut goal_def =
            Definition::from_script("GOAL", "Goal", listener_script).expect("goal compiles");
        goal_def.set_category(1 << 5); // C4D_Goal
        engine
            .register_definition(goal_def)
            .expect("goal registers");
        let mut rule_def =
            Definition::from_script("RULE", "Rule", listener_script).expect("rule compiles");
        rule_def.set_category(1 << 19); // C4D_Rule
        engine
            .register_definition(rule_def)
            .expect("rule registers");
        engine
            .register_definition(
                Definition::from_script("PLAI", "Plain", listener_script).expect("plain compiles"),
            )
            .expect("plain registers");
        engine
            .install_scenario_script(
                "Scenario",
                r#"
                global func Roll(n) { return n * 3; }
                "#,
            )
            .expect("scenario installs");

        let caller = engine
            .spawn_object(SpawnConfig::new("CLLR"))
            .expect("caller spawns");
        let goal = engine
            .spawn_object(SpawnConfig::new("GOAL"))
            .expect("goal spawns");
        let rule = engine
            .spawn_object(SpawnConfig::new("RULE"))
            .expect("rule spawns");
        let plain = engine
            .spawn_object(SpawnConfig::new("PLAI"))
            .expect("plain spawns");
        engine.tick().expect("tick succeeds");

        let caller_idx = engine.find_object_index(caller).expect("caller exists");
        let result = engine
            .call_object_function(caller_idx, "Shout", Vec::new())
            .expect("Shout succeeds");
        assert_eq!(
            result,
            Value::Int(15),
            "only the scenario script's result returns (goal/rule results discarded)"
        );
        for (id, expected) in [(goal, Some(&Value::Int(5))), (rule, Some(&Value::Int(5)))] {
            let idx = engine.find_object_index(id).expect("listener exists");
            assert_eq!(
                engine.objects[idx].state.local_vars.get("hits"),
                expected,
                "goal/rule objects were each called once"
            );
        }
        let plain_idx = engine.find_object_index(plain).expect("plain exists");
        assert_eq!(
            engine.objects[plain_idx].state.local_vars.get("hits"),
            None,
            "plain-category objects are not part of the broadcast"
        );
    }

    #[test]
    fn create_menu_opens_a_script_menu_and_get_menu_reads_it_like_cpp() {
        // FnCreateMenu (C4Script.cpp:1426-1459): inits the object's menu with
        // Identification = idMenuID ? idMenuID : iSymbol (C4Menu::InitMenu,
        // C4Menu.cpp:355). FnGetMenu (C4Script.cpp:1418-1424): an ACTIVE
        // menu returns that Identification, no menu returns C4MN_None (0).
        let script = r#"
        func OpenMenu() { return CreateMenu(WIPF, this(), this(), 0, "Choose"); }
        func OpenAliased() { return CreateMenu(WIPF, this(), this(), 0, "Choose", 0, 1, 0, MENU); }
        func ReadMenu() { return GetMenu(this()); }
        "#;
        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("CLNK", "Clonk", script).expect("script compiles"),
            )
            .expect("definition registers");
        let clonk = engine
            .spawn_object(SpawnConfig::new("CLNK"))
            .expect("clonk spawns");
        engine.tick().expect("tick succeeds");

        let idx = engine.find_object_index(clonk).expect("clonk exists");
        assert_eq!(
            engine
                .call_object_function(idx, "ReadMenu", Vec::new())
                .expect("ReadMenu succeeds"),
            Value::Int(0),
            "no menu -> C4MN_None (C4Script.cpp:1423)"
        );
        assert_eq!(
            engine
                .call_object_function(idx, "OpenMenu", Vec::new())
                .expect("OpenMenu succeeds"),
            Value::Bool(true),
            "FnCreateMenu returns true on success"
        );
        let idx = engine.find_object_index(clonk).expect("clonk exists");
        assert_eq!(
            engine
                .call_object_function(idx, "ReadMenu", Vec::new())
                .expect("ReadMenu succeeds"),
            Value::C4Id("WIPF".into()),
            "active menu -> its Identification (the symbol id by default)"
        );
        let menu = engine
            .debug_object_menu(clonk.as_u64())
            .expect("clonk exists")
            .expect("menu is open");
        assert_eq!(menu.style, 0, "C4MN_Style_Normal");
        assert!(!menu.permanent, "fPermanent defaults false");
        assert_eq!(menu.selection, -1, "C4Menu::Default Selection (-1)");
        assert_eq!(
            menu.command_object,
            Some(clonk),
            "pCommandObj -> CB_Object callbacks"
        );

        // idMenuID overrides the symbol as Identification (C4Script.cpp:1452).
        assert_eq!(
            engine
                .call_object_function(idx, "OpenAliased", Vec::new())
                .expect("OpenAliased succeeds"),
            Value::Bool(true)
        );
        let idx = engine.find_object_index(clonk).expect("clonk exists");
        assert_eq!(
            engine
                .call_object_function(idx, "ReadMenu", Vec::new())
                .expect("ReadMenu succeeds"),
            Value::C4Id("MENU".into()),
            "idMenuID wins over the symbol id"
        );
        let menu = engine
            .debug_object_menu(clonk.as_u64())
            .expect("clonk exists")
            .expect("menu is open");
        assert_eq!(menu.style, 1, "iStyle stored (C4MN_Style_Context)");
    }

    #[test]
    fn close_menu_and_menu_query_cancel_follow_cpp_close_semantics() {
        // FnCloseMenu (C4Script.cpp:4309-4314) forces the close —
        // C4Menu::TryClose(fOK=true) skips IsCloseDenied (C4Menu.cpp:
        // 317-320). FnCreateMenu's clear of the OLD menu is soft
        // (CloseMenu(false), C4Script.cpp:1447): a truthy MenuQueryCancel
        // (C4ObjectMenu::IsCloseDenied, C4ObjectMenu.cpp:56-75) keeps the
        // old menu and fails the new one.
        let script = r#"
        local deny;
        func SetDeny(flag) { deny = flag; }
        func MenuQueryCancel() { return deny; }
        func OpenMenu() { return CreateMenu(WIPF, this(), this(), 0, "Choose"); }
        func OpenOther() { return CreateMenu(MENU, this(), this(), 0, "Other"); }
        func Shut() { return CloseMenu(this()); }
        func ReadMenu() { return GetMenu(this()); }
        "#;
        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("CLNK", "Clonk", script).expect("script compiles"),
            )
            .expect("definition registers");
        let clonk = engine
            .spawn_object(SpawnConfig::new("CLNK"))
            .expect("clonk spawns");
        engine.tick().expect("tick succeeds");

        let call = |engine: &mut Engine, name: &str| {
            let idx = engine.find_object_index(clonk).expect("clonk exists");
            engine
                .call_object_function(idx, name, Vec::new())
                .expect("call succeeds")
        };

        // CloseMenu without a menu still succeeds (C4Object::CloseMenu
        // returns true when Menu is null, C4Object.cpp:2009-2016).
        assert_eq!(call(&mut engine, "Shut"), Value::Bool(true));

        // Open, then force-close despite MenuQueryCancel denying.
        assert_eq!(call(&mut engine, "OpenMenu"), Value::Bool(true));
        let idx = engine.find_object_index(clonk).expect("clonk exists");
        engine
            .call_object_function(idx, "SetDeny", vec![Value::Int(1)])
            .expect("SetDeny succeeds");
        assert_eq!(
            call(&mut engine, "Shut"),
            Value::Bool(true),
            "forced close skips MenuQueryCancel"
        );
        assert_eq!(call(&mut engine, "ReadMenu"), Value::Int(0));

        // Open again; the denied SOFT close makes a second CreateMenu fail
        // and keeps the old menu.
        assert_eq!(call(&mut engine, "OpenMenu"), Value::Bool(true));
        assert_eq!(
            call(&mut engine, "OpenOther"),
            Value::Bool(false),
            "MenuQueryCancel denies replacing the menu"
        );
        assert_eq!(
            call(&mut engine, "ReadMenu"),
            Value::C4Id("WIPF".into()),
            "the old menu survives the denied replace"
        );

        // Allow the close: the replace goes through.
        let idx = engine.find_object_index(clonk).expect("clonk exists");
        engine
            .call_object_function(idx, "SetDeny", vec![Value::Int(0)])
            .expect("SetDeny succeeds");
        assert_eq!(call(&mut engine, "OpenOther"), Value::Bool(true));
        assert_eq!(call(&mut engine, "ReadMenu"), Value::C4Id("MENU".into()));
    }

    #[test]
    fn add_menu_item_composes_commands_and_counts_like_cpp() {
        // FnAddMenuItem (C4Script.cpp:1471-1734): no menu -> false; new-style
        // commands (any non-identifier char) go through the %d->%s sprintf
        // hack (:1560-1571), old-style function names compose
        // "Fn(ID,param[,1][,value])" (:1573-1597); a zero count becomes
        // C4MN_Item_NoCount unless C4MN_Add_ForceCount (:1726); items without
        // a command are not selectable (:1729) and the first selectable item
        // grabs the initial selection (C4Menu::AddItem, C4Menu.cpp:424).
        let script = r#"
        func TryEarly() { return AddMenuItem("x", "Cmd", WIPF, this()); }
        func OpenMenu() { return CreateMenu(WIPF, this(), this(), 0, "Choose"); }
        func AddPlain() { return AddMenuItem("Info", "", WIPF, this()); }
        func AddNew() { return AddMenuItem("Easy", "SetDifficulty(0)", WIPF, this()); }
        func AddFmt() { return AddMenuItem("Fmt", "Choose(%d,%d)", WIPF, this(), 0, 5); }
        func AddOld() { return AddMenuItem("Old %s", "Choose", CLNK, this(), 3, 7, "info"); }
        func AddValued() { return AddMenuItem("Val", "Choose", CLNK, this(), 0, "txt", 0, 384, 0, 42); }
        "#;
        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("CLNK", "Clonk", script).expect("script compiles"),
            )
            .expect("definition registers");
        let clonk = engine
            .spawn_object(SpawnConfig::new("CLNK"))
            .expect("clonk spawns");
        engine.tick().expect("tick succeeds");

        let call = |engine: &mut Engine, name: &str| {
            let idx = engine.find_object_index(clonk).expect("clonk exists");
            engine
                .call_object_function(idx, name, Vec::new())
                .expect("call succeeds")
        };

        assert_eq!(
            call(&mut engine, "TryEarly"),
            Value::Bool(false),
            "no menu -> false (C4Script.cpp:1475)"
        );
        assert_eq!(call(&mut engine, "OpenMenu"), Value::Bool(true));
        for adder in ["AddPlain", "AddNew", "AddFmt", "AddOld", "AddValued"] {
            assert_eq!(call(&mut engine, adder), Value::Bool(true), "{adder}");
        }

        let menu = engine
            .debug_object_menu(clonk.as_u64())
            .expect("clonk exists")
            .expect("menu is open");
        assert_eq!(menu.items.len(), 5);

        // Command-less item: never selectable, no-count sentinel.
        let plain = &menu.items[0];
        assert_eq!(plain.command, "");
        assert!(!plain.selectable);
        assert_eq!(plain.count, 12_345_678, "C4MN_Item_NoCount");

        // New style without %d: both commands are the literal text.
        let easy = &menu.items[1];
        assert_eq!(easy.command, "SetDifficulty(0)");
        assert_eq!(easy.command2, "SetDifficulty(0)");
        assert!(easy.selectable);

        // New style with %d: the FIRST %d takes the parameter, the second
        // gets 0 (left) / 1 (right) (C4Script.cpp:1563-1570).
        let fmt = &menu.items[2];
        assert_eq!(fmt.command, "Choose(5,0)");
        assert_eq!(fmt.command2, "Choose(5,1)");

        // Old style: Fn(ID,param) / Fn(ID,param,1); caption %s takes the
        // item def's name (C4Script.cpp:1492-1505); explicit count kept.
        let old = &menu.items[3];
        assert_eq!(old.caption, "Old Clonk");
        assert_eq!(old.command, "Choose(CLNK,7)");
        assert_eq!(old.command2, "Choose(CLNK,7,1)");
        assert_eq!(old.count, 3);
        assert_eq!(old.item_id, "CLNK");

        // C4MN_Add_PassValue (128) + C4MN_Add_ForceCount (256): string
        // parameters are quoted, the value rides along, count 0 stays 0.
        let valued = &menu.items[4];
        assert_eq!(valued.command, "Choose(CLNK,\"txt\",0,42)");
        assert_eq!(valued.command2, "Choose(CLNK,\"txt\",1,42)");
        assert_eq!(valued.count, 0);
        assert_eq!(valued.value, Some(42));

        // The first SELECTABLE item took the initial selection
        // (item 0 is not selectable, so index 1).
        assert_eq!(menu.selection, 1);
    }

    #[test]
    fn select_menu_item_moves_selection_and_fires_on_menu_selection_like_cpp() {
        // FnSelectMenuItem (C4Script.cpp:1736-1741) -> C4Menu::SetSelection
        // (C4Menu.cpp:557-594): only SELECTABLE items move the selection,
        // but the call returns true whenever a menu is active, and
        // fDoCalls fires OnMenuSelection(Selection, ParentObject) on the
        // command object EITHER way (C4ObjectMenu::OnSelectionChanged,
        // C4ObjectMenu.cpp:93-104) — with the (possibly unchanged) final
        // selection.
        let script = r#"
        local lastSel;
        func OnMenuSelection(sel, menuObj) { lastSel = sel; }
        func NoMenu() { return SelectMenuItem(0, this()); }
        func OpenMenu() {
            CreateMenu(WIPF, this(), this(), 0, "Choose");
            AddMenuItem("A", "CmdA", WIPF, this());
            AddMenuItem("B", "CmdB", WIPF, this());
            AddMenuItem("C", "", WIPF, this());
            return 1;
        }
        func Sel(i) { return SelectMenuItem(i, this()); }
        "#;
        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("CLNK", "Clonk", script).expect("script compiles"),
            )
            .expect("definition registers");
        let clonk = engine
            .spawn_object(SpawnConfig::new("CLNK"))
            .expect("clonk spawns");
        engine.tick().expect("tick succeeds");

        let call = |engine: &mut Engine, name: &str, args: Vec<Value>| {
            let idx = engine.find_object_index(clonk).expect("clonk exists");
            engine
                .call_object_function(idx, name, args)
                .expect("call succeeds")
        };
        let last_sel = |engine: &Engine| {
            let idx = engine.find_object_index(clonk).expect("clonk exists");
            engine.objects[idx]
                .state
                .local_vars
                .get("lastSel")
                .cloned()
                .unwrap_or(Value::Nil)
        };

        assert_eq!(
            call(&mut engine, "NoMenu", Vec::new()),
            Value::Bool(false),
            "no menu -> false (C4Script.cpp:1739)"
        );
        assert_eq!(call(&mut engine, "OpenMenu", Vec::new()), Value::Int(1));

        // Selectable item: selection moves, callback sees the new index.
        assert_eq!(
            call(&mut engine, "Sel", vec![Value::Int(1)]),
            Value::Bool(true)
        );
        assert_eq!(last_sel(&engine), Value::Int(1));
        let menu = engine
            .debug_object_menu(clonk.as_u64())
            .expect("clonk exists")
            .expect("menu is open");
        assert_eq!(menu.selection, 1);

        // Non-selectable item: selection stays, call still true, callback
        // fires with the OLD selection.
        assert_eq!(
            call(&mut engine, "Sel", vec![Value::Int(2)]),
            Value::Bool(true)
        );
        let menu = engine
            .debug_object_menu(clonk.as_u64())
            .expect("clonk exists")
            .expect("menu is open");
        assert_eq!(menu.selection, 1, "item without command is not selectable");
        assert_eq!(last_sel(&engine), Value::Int(1));

        // Out of range behaves the same.
        assert_eq!(
            call(&mut engine, "Sel", vec![Value::Int(9)]),
            Value::Bool(true)
        );
        let menu = engine
            .debug_object_menu(clonk.as_u64())
            .expect("clonk exists")
            .expect("menu is open");
        assert_eq!(menu.selection, 1);
    }

    #[test]
    fn landscape_width_and_height_report_gback_dimensions_like_cpp() {
        // FnLandscapeWidth/FnLandscapeHeight (C4Script.cpp:3077-3085):
        // GBackWdt/GBackHgt — the wild-horse ContactRight turn check reads
        // them (Goldrush WildHorse.c).
        let script = r#"
        func ReadWidth() { return LandscapeWidth(); }
        func ReadHeight() { return LandscapeHeight(); }
        "#;
        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("HORS", "Horse", script).expect("script compiles"),
            )
            .expect("definition registers");
        engine.set_landscape(Landscape::flat_with_material(23, 41, None));
        let horse = engine
            .spawn_object(SpawnConfig::new("HORS"))
            .expect("horse spawns");
        engine.tick().expect("tick succeeds");

        let idx = engine.find_object_index(horse).expect("horse exists");
        assert_eq!(
            engine
                .call_object_function(idx, "ReadWidth", Vec::new())
                .expect("ReadWidth succeeds"),
            Value::Int(23)
        );
        assert_eq!(
            engine
                .call_object_function(idx, "ReadHeight", Vec::new())
                .expect("ReadHeight succeeds"),
            Value::Int(41)
        );
    }

    #[test]
    fn punch_follows_object_com_punch_semantics_like_cpp() {
        // FnPunch (C4Script.cpp:328-332) -> ObjectComPunch
        // (C4ObjectCom.cpp:735-767): zero punch derives from the Fight
        // physicals (clamp(5*attacker/target, 0, 10)); QueryCatchBlow
        // halves punch > 1 and stops the blow (return false, no tumble);
        // energy drops -punch% and ComDir stops either way; punch >= 10
        // tries Tumble (xdir FIXED100(150)*tdir, ydir -2), else GetPunched
        // (xdir FIXED100(250)*tdir, ydir 0), each firing CatchBlow(punch,
        // attacker) on success.
        let attacker_script = r#"
        func Bite(target, strength) { return Punch(target, strength); }
        "#;
        let victim_script = r#"
        local catchBlow;
        local stopBlows;
        func QueryCatchBlow(byObj) { return stopBlows; }
        func CatchBlow(level, byObj) { catchBlow = level; }
        "#;
        let mut attacker_def = Definition::from_script("SNKE", "Snake", attacker_script)
            .expect("attacker compiles");
        attacker_def.set_physical(PhysicalInfo {
            fight: 50_000,
            ..PhysicalInfo::default()
        });
        let mut victim_def =
            Definition::from_script("CLNK", "Clonk", victim_script).expect("victim compiles");
        let mut actions = HashMap::new();
        actions.insert("Idle".to_string(), ActionSpec::default());
        actions.insert("GetPunched".to_string(), ActionSpec::default());
        actions.insert("Tumble".to_string(), ActionSpec::default());
        victim_def.configure_actions(Some("Idle".to_string()), actions);
        victim_def.set_physical(PhysicalInfo {
            fight: 25_000,
            energy: 50_000,
            ..PhysicalInfo::default()
        });
        // A victim without Tumble/GetPunched AND without Fight: the derived
        // punch stays zero -> Punch is a no-op success (C4ObjectCom.cpp:741).
        let pillow_def =
            Definition::from_script("PILW", "Pillow", victim_script).expect("pillow compiles");

        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(attacker_def)
            .expect("attacker registers");
        engine
            .register_definition(victim_def)
            .expect("victim registers");
        engine
            .register_definition(pillow_def)
            .expect("pillow registers");
        let snake = engine
            .spawn_object(SpawnConfig::new("SNKE").with_position(Vector2::new(50, 50)))
            .expect("snake spawns");
        let spawn_victim = |engine: &mut Engine| {
            engine
                .spawn_object(
                    SpawnConfig::new("CLNK")
                        .with_position(Vector2::new(52, 50))
                        .with_alive(true)
                        .with_energy(50_000),
                )
                .expect("victim spawns")
        };
        let v_regular = spawn_victim(&mut engine);
        let v_hard = spawn_victim(&mut engine);
        let v_catcher = spawn_victim(&mut engine);
        let v_derived = spawn_victim(&mut engine);
        let pillow = engine
            .spawn_object(
                SpawnConfig::new("PILW")
                    .with_position(Vector2::new(52, 50))
                    .with_alive(true)
                    .with_energy(50_000),
            )
            .expect("pillow spawns");
        engine.tick().expect("tick succeeds");

        // tdir = +1 for a right-facing attacker (C4ObjectCom.cpp:745).
        let snake_idx = engine.find_object_index(snake).expect("snake exists");
        engine.objects[snake_idx].state.direction = Direction::Right;
        // A pre-punch ComDir so the COMD_Stop write is observable.
        let idx = engine.find_object_index(v_regular).expect("victim exists");
        engine.objects[idx].state.command_direction = CommandDirection::Right;

        let bite = |engine: &mut Engine, target: ObjectId, strength: Option<i32>| {
            let idx = engine.find_object_index(snake).expect("snake exists");
            let args = vec![
                Value::Object(target.as_u64()),
                strength.map(Value::Int).unwrap_or(Value::Nil),
            ];
            engine
                .call_object_function(idx, "Bite", args)
                .expect("Bite succeeds")
        };

        // Regular punch (8 < 10): GetPunched, xdir FIXED100(250), ydir 0.
        assert_eq!(bite(&mut engine, v_regular, Some(8)), Value::Bool(true));
        let idx = engine.find_object_index(v_regular).expect("victim exists");
        let victim = &engine.objects[idx];
        assert_eq!(victim.state.energy, 42_000, "-8% of C4MaxPhysical");
        assert_eq!(victim.state.action.name, "GetPunched");
        assert_eq!(victim.fixed_velocity.x, fixed100(250));
        assert_eq!(victim.fixed_velocity.y, C4Fixed::ZERO);
        assert_eq!(victim.state.command_direction, CommandDirection::Stop);
        assert_eq!(
            victim.state.local_vars.get("catchBlow"),
            Some(&Value::Int(8)),
            "CatchBlow(level, byObj) fired"
        );

        // Hard punch (>= 10): Tumble with the tumble fling.
        assert_eq!(bite(&mut engine, v_hard, Some(12)), Value::Bool(true));
        let idx = engine.find_object_index(v_hard).expect("victim exists");
        let victim = &engine.objects[idx];
        assert_eq!(victim.state.energy, 38_000, "-12%");
        assert_eq!(victim.state.action.name, "Tumble");
        assert_eq!(victim.fixed_velocity.x, fixed100(150));
        assert_eq!(victim.fixed_velocity.y, itofix(-2));

        // Caught blow: halved damage, no tumble, Punch returns false.
        let idx = engine.find_object_index(v_catcher).expect("victim exists");
        engine.objects[idx]
            .state
            .local_vars
            .insert("stopBlows".to_string(), Value::Int(1));
        assert_eq!(bite(&mut engine, v_catcher, Some(8)), Value::Bool(false));
        let idx = engine.find_object_index(v_catcher).expect("victim exists");
        let victim = &engine.objects[idx];
        assert_eq!(victim.state.energy, 46_000, "halved to -4%");
        assert_ne!(victim.state.action.name, "GetPunched", "no fling");

        // Zero punch derives from the Fight physicals:
        // clamp(5*50000/25000, 0, 10) = 10 -> hard punch.
        assert_eq!(bite(&mut engine, v_derived, None), Value::Bool(true));
        let idx = engine.find_object_index(v_derived).expect("victim exists");
        assert_eq!(engine.objects[idx].state.action.name, "Tumble");

        // No Fight physical on the target: punch stays 0 -> no-op success.
        assert_eq!(bite(&mut engine, pillow, None), Value::Bool(true));
        let idx = engine.find_object_index(pillow).expect("pillow exists");
        assert_eq!(engine.objects[idx].state.energy, 50_000, "untouched");
    }

    #[test]
    fn set_command_dispatches_to_a_foreign_object_like_cpp() {
        // FnSetCommand (C4Script.cpp:840-868): pObj is the FIRST parameter
        // and may be ANY object — GoldRush's StopClonk helper halts OTHER
        // clonks (SetCommand(pTarget, "None"), Helpers.c:94) and dialogue
        // NPCs get MoveTo orders. An unknown command name clears the
        // target's command stack and returns false (:847-851).
        let script = r#"
        func Order(target) { return SetCommand(target, "MoveTo", 0, 44, 55); }
        func Halt(target) { return SetCommand(target, "None"); }
        "#;
        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(
                Definition::from_script("BOSS", "Boss", script).expect("script compiles"),
            )
            .expect("boss registers");
        engine
            .register_definition(
                Definition::from_script("MNON", "Minion", "").expect("minion compiles"),
            )
            .expect("minion registers");
        let boss = engine
            .spawn_object(SpawnConfig::new("BOSS"))
            .expect("boss spawns");
        let minion = engine
            .spawn_object(SpawnConfig::new("MNON"))
            .expect("minion spawns");
        engine.tick().expect("tick succeeds");

        let boss_idx = engine.find_object_index(boss).expect("boss exists");
        assert_eq!(
            engine
                .call_object_function(
                    boss_idx,
                    "Order",
                    vec![Value::Object(minion.as_u64())],
                )
                .expect("Order succeeds"),
            Value::Bool(true)
        );
        let minion_idx = engine.find_object_index(minion).expect("minion exists");
        assert_eq!(
            engine.objects[minion_idx].commands.command_names(),
            vec!["MoveTo".to_string()],
            "the foreign target carries the command"
        );

        let boss_idx = engine.find_object_index(boss).expect("boss exists");
        assert_eq!(
            engine
                .call_object_function(boss_idx, "Halt", vec![Value::Object(minion.as_u64())])
                .expect("Halt succeeds"),
            Value::Bool(false),
            "unknown command name -> ClearCommands + false"
        );
        let minion_idx = engine.find_object_index(minion).expect("minion exists");
        assert!(
            engine.objects[minion_idx].commands.command_names().is_empty(),
            "\"None\" cleared the foreign stack"
        );
    }

    #[test]
    fn do_damage_asks_effects_for_non_living_and_fires_callback() {
        // C4Object::DoDamage (C4Object.cpp:1330-1343): NON-living things ask
        // their effects first (the inverse of DoEnergy's Alive gate), the
        // damage clamps at zero, and the Damage script callback fires with
        // (change, causedBy).
        let script = r#"
        global func Initialize(state, random) {
            return { effects = [ { op = "add", name = "Shell", priority = 100, interval = 0 } ] };
        }

        global func FxShellDamage(state, effect, damage, damage_type, cause_plr) {
            return damage / 2;
        }

        func Damage(change, caused_by) {
            return nil;
        }

        global func Step(state, frame, random) {
            return nil;
        }
        "#;

        let call_log: Arc<Mutex<Vec<String>>> = Arc::new(Mutex::new(Vec::new()));
        let mut hooks = DebuggerHooks::new();
        {
            let call_log = Arc::clone(&call_log);
            hooks.set_on_call(move |name, _args| {
                call_log.lock().unwrap().push(name.to_string());
            });
        }
        let mut definition =
            Definition::from_script("Actor", "Actor", script).expect("script compiles");
        definition.set_debugger_hooks(hooks);
        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(definition)
            .expect("definition registers");

        // Non-living: the effect halves the damage.
        let crate_id = engine
            .spawn_object(SpawnConfig::new("Actor").with_alive(false))
            .expect("spawn succeeds");
        engine.tick().expect("tick succeeds");
        let idx = engine.find_object_index(crate_id).expect("object exists");
        engine.change_object_damage(idx, 10, C4FX_CALL_DMG_SCRIPT, 3);
        assert_eq!(engine.objects[idx].state.damage, 5);
        let calls = call_log.lock().unwrap().clone();
        assert!(
            calls.iter().any(|name| name == "Damage"),
            "the Damage script callback fires (C4Object.cpp:1342)"
        );

        // Living: effects are NOT asked for damage (C4Object.cpp:1333).
        let clonk_id = engine
            .spawn_object(SpawnConfig::new("Actor").with_alive(true))
            .expect("spawn succeeds");
        engine.tick().expect("tick succeeds");
        let idx = engine.find_object_index(clonk_id).expect("object exists");
        engine.change_object_damage(idx, 10, C4FX_CALL_DMG_SCRIPT, 3);
        assert_eq!(engine.objects[idx].state.damage, 10);
    }

    #[test]
    fn do_energy_asks_fx_damage_effects_first() {
        // C4Object::DoEnergy asks living things' effects before applying
        // (C4Object.cpp:1355-1359); C4Effect::DoDamage walks the effects in
        // list order — each Fx<Name>Damage return REPLACES the damage
        // (getInt), and a zeroed damage aborts both the walk and DoEnergy
        // (C4Effect.cpp:312-322).
        let script = r#"
        global func Initialize(state, random) {
            return { effects = [
                { op = "add", name = "Armor", priority = 200, interval = 0 },
                { op = "add", name = "Ward", priority = 100, interval = 0 }
            ] };
        }

        global func FxWardDamage(state, effect, damage, damage_type, cause_plr) {
            if (damage_type == 35) {
                return 0;
            }
            return damage;
        }

        global func FxArmorDamage(state, effect, damage, damage_type, cause_plr) {
            return damage / 2;
        }

        global func Step(state, frame, random) {
            return nil;
        }
        "#;

        let definition =
            Definition::from_script("Actor", "Actor", script).expect("script compiles");
        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(definition)
            .expect("definition registers");
        let id = engine
            .spawn_object(
                SpawnConfig::new("Actor")
                    .with_alive(true)
                    .with_energy(50_000),
            )
            .expect("spawn succeeds");
        engine.tick().expect("tick succeeds");
        let idx = engine.find_object_index(id).expect("object exists");

        // List order is ascending priority: Ward (100) runs before Armor
        // (200). A script-cause hit of -10 passes Ward untouched and is
        // -10% = -10000 raw (C4Object.cpp:1347), halved by Armor: -5000.
        engine.change_object_energy(idx, -10, C4FX_CALL_ENG_SCRIPT, 3);
        assert_eq!(engine.objects[idx].state.energy, 45_000);

        // A fire-cause hit is zeroed by Ward; the zero aborts the walk AND
        // DoEnergy (C4Object.cpp:1358) — Armor never halves, energy keeps.
        engine.change_object_energy(idx, -10, C4FX_CALL_ENG_FIRE, 3);
        assert_eq!(engine.objects[idx].state.energy, 45_000);
    }

    #[test]
    fn do_energy_clamps_to_physical_energy_ceiling() {
        let script = r#"
        global func Initialize(state, random) {
            return nil;
        }

        global func Step(state, frame, random) {
            return nil;
        }
        "#;

        let mut definition = Definition::from_script("Clonk", "Clonk", script).unwrap();
        // DoEnergy bounds energy by GetPhysical()->Energy (C4Object.cpp:1361);
        // 50000 on the 0..C4MaxPhysical scale is 50 percent points.
        definition.set_physical(PhysicalInfo {
            energy: 50_000,
            ..PhysicalInfo::default()
        });
        let legacy_definition = Definition::from_script("Crate", "Crate", script).unwrap();

        let mut engine = Engine::with_seed(7);
        engine
            .register_definition(definition)
            .expect("definition registers");
        engine
            .register_definition(legacy_definition)
            .expect("legacy definition registers");

        let clonk_id = engine
            .spawn_object(SpawnConfig::new("Clonk").with_energy(40_000))
            .expect("clonk spawns");
        let clonk_idx = engine.find_object_index(clonk_id).expect("clonk exists");
        engine.change_object_energy(clonk_idx, 30, C4FX_CALL_ENG_SCRIPT, -1);
        assert_eq!(
            engine.objects[clonk_idx].state.energy, 50_000,
            "gain (+30% = +30000 raw) clamps to GetPhysical()->Energy"
        );

        // Documented deviation: zero-physical fixture definitions keep the
        // legacy unclamped ceiling instead of C++'s clamp-to-zero.
        let crate_id = engine
            .spawn_object(SpawnConfig::new("Crate").with_energy(40))
            .expect("crate spawns");
        let crate_idx = engine.find_object_index(crate_id).expect("crate exists");
        engine.change_object_energy(crate_idx, 30, C4FX_CALL_ENG_SCRIPT, -1);
        assert_eq!(engine.objects[crate_idx].state.energy, 30_040);
    }

    #[test]
    fn walk_procedure_uses_walk_physical_limit_and_const_accel() {
        let script = r#"
        global func Initialize(state, random) {
            return nil;
        }

        global func Step(state, frame, random) {
            return nil;
        }
        "#;

        let mut definition = Definition::from_script("Walker", "Walker", script).unwrap();
        let mut actions = HashMap::new();
        actions.insert(
            "Walk".to_string(),
            ActionSpec::default().with_procedure("walk"),
        );
        definition.configure_actions(Some("Walk".to_string()), actions);
        definition.set_physical(PhysicalInfo {
            walk: 35_000,
            ..PhysicalInfo::default()
        });

        let mut engine = Engine::with_seed(5);
        engine
            .register_definition(definition)
            .expect("definition registers");
        engine.set_physics(
            PhysicsSettings::new(0, 20, -20)
                .with_max_horizontal_speed(20)
                .expect("horizontal speed valid"),
        );

        let id = engine
            .spawn_object(
                SpawnConfig::new("Walker")
                    .with_position(Vector2::new(0, 0))
                    .with_command_direction(CommandDirection::Right),
            )
            .expect("walker spawns");
        let idx = engine.find_object_index(id).expect("walker exists");

        // DFA_WALK (C4Object.cpp:4771-4786): xdir += WalkAccel = FIXED100(50)
        // (C4Movement.cpp:34) = raw 32768 per frame, clamped to
        // lLimit = ValByPhysical(280, 35000) = itofix(35000*56, 2000000)
        // = raw 64225.
        engine.tick().expect("tick succeeds");
        assert_eq!(engine.objects[idx].fixed_velocity.x.val(), 32768);
        engine.tick().expect("tick succeeds");
        assert_eq!(engine.objects[idx].fixed_velocity.x.val(), 64225);
    }

    #[test]
    fn scale_procedure_uses_scale_physical_limit_and_trains_at_limit() {
        let script = r#"
        global func Initialize(state, random) {
            return nil;
        }

        global func Step(state, frame, random) {
            return nil;
        }
        "#;

        let mut definition = Definition::from_script("Climber", "Climber", script).unwrap();
        let mut actions = HashMap::new();
        actions.insert(
            "Scale".to_string(),
            ActionSpec::default().with_procedure("scale"),
        );
        definition.configure_actions(Some("Scale".to_string()), actions);
        definition.set_physical(PhysicalInfo {
            scale: 30_000,
            ..PhysicalInfo::default()
        });

        let mut engine = Engine::with_seed(5);
        engine
            .register_definition(definition)
            .expect("definition registers");
        engine.set_physics(PhysicsSettings::new(0, 20, -20));

        let id = engine
            .spawn_object(
                SpawnConfig::new("Climber")
                    .with_crew_member(true)
                    .with_position(Vector2::new(0, 0))
                    .with_command_direction(CommandDirection::Up),
            )
            .expect("climber spawns");
        let idx = engine.find_object_index(id).expect("climber exists");

        // DFA_SCALE (C4Object.cpp:4805-4837): ydir -= WalkAccel (raw 32768),
        // clamped to lLimit = ValByPhysical(200, 30000)
        // = itofix(30000*40, 2000000) = raw 39321.
        engine.tick().expect("tick succeeds");
        assert_eq!(engine.objects[idx].fixed_velocity.y.val(), -32768);
        engine.tick().expect("tick succeeds");
        assert_eq!(engine.objects[idx].fixed_velocity.y.val(), -39321);
        assert_eq!(engine.objects[idx].state.info_physical, None);

        // Tick5 at-limit training (C4Object.cpp:4810-4812): frame 5 sees
        // |ydir| == lLimit and trains Scale by 1.
        engine.tick().expect("tick succeeds");
        engine.tick().expect("tick succeeds");
        engine.tick().expect("tick succeeds");
        let trained = engine.objects[idx]
            .state
            .info_physical
            .expect("at-limit Tick5 training clones the physicals");
        assert_eq!(trained.scale, 30_001);
    }

